// Custom PDF Parser for "GNO Hesaplayıcı | Pro" format
// This format is generated by the app itself or a specific tool.

function extractCustomFormat(pages) {
    const fullText = pages.join("\n");
    if (!fullText.includes("GNO Hesaplayıcı") && !fullText.includes("AKTS Modu") && !fullText.includes("UK (Kredi) Modu")) {
        return [];
    }

    const mode = fullText.includes("UK (Kredi) Modu") ? "UK" : "AKTS";
    let currentSemester = "Geri Yüklenen";
    let indexCounter = 0;
    const extracted = [];

    pages.forEach(pageText => {
        const lines = pageText.split('\n');
        lines.forEach(line => {
            line = line.trim();
            if (!line) return;

            if (line.includes("DNO:")) {
                const parts = line.split("DNO:");
                const sem = parts[0].trim();
                // Remove calendar icon if present (unicode usually)
                if (sem) currentSemester = sem.replace(/[^\w\s\d-]/g, "").trim();
                return;
            }

            const parts = line.split(/\s+/);
            if (parts.length < 3) return;

            const grade = parts[parts.length - 1];
            // Grade validation (short)
            if (grade.length > 3 && grade !== "Başarılı" && grade !== "Başarısız") return;

            const creditStr = parts[parts.length - 2];
            if (!/^\d+(\.\d+)?$/.test(creditStr)) return;

            const code = parts[0];
            if (!/\d/.test(code)) return; // Code usually has digits

            // Name is everything between Code and Credit
            const nameTokens = parts.slice(1, parts.length - 2);
            const name = nameTokens.join(" ");

            const val = parseFloat(creditStr);
            const akts = mode === "AKTS" ? Math.round(val) : 0;
            const uk = mode === "UK" ? val : 0;

            extracted.push({
                id: indexCounter++,
                semester: currentSemester,
                code: code,
                name: name,
                akts: akts,
                uk: uk,
                grade: grade,
                status: 'Z'
            });
        });
    });
    return extracted;
}

// --- Hacettepe Official Transcript Parser (Fallback #2) ---
// Handles the official "Not Durum Belgesi" format generated by Stimulsoft Reports.
// Column order per course row (left-to-right): Code | Name | Durum(int) | Grade | Puan | AKTS
// Verified: BBM101 C1 → 15 6 means Puan=C1(2.50)×6=15, AKTS=6 ✓
// Uses look-ahead state machine in case PDF.js splits row data across multiple lines.

function extractHacettepeOfficial(pages) {
    const fullText = pages.join('\n');

    // --- Format detection (lenient: any one match is enough) ---
    const isHacettepe =
        fullText.includes('Hacettepe') ||
        fullText.includes('Durum Belgesi') ||
        fullText.includes('Transkript') ||
        fullText.includes('\u00d6\u011frenci \u0130\u015fleri'); // "Öğrenci İşleri" unicode safe

    if (!isHacettepe) {
        console.log('[HacettepeParser] Format not detected, skipping.');
        return null;
    }

    console.log('[HacettepeParser] Format detected, starting parse...');

    // All valid Hacettepe grade tokens
    const validGrades = new Set([
        'A1', 'A2', 'A3',
        'B1', 'B2', 'B3',
        'C1', 'C2', 'C3',
        'D',
        'F1', 'F2', 'F3', 'F4', 'F5', 'F6',
        'G', 'K', 'M', '--'
    ]);

    // Course code: 2–5 uppercase Turkish/Latin letters + 3–4 digits + optional trailing letter
    // Covers: BBM101, AİT203, İNG111, MÜH103, İST292, SEC467, AIN312 ...
    const codeRe = /^([A-Z\u00c7\u011e\u0130\u00d6\u015e\u00dc]{2,5}\d{3,4}[A-Z]?)$/;

    // Semester: "2023-2024 Güz", "2024-2025 Bahar Muafiyet"
    const semRe = /^(\d{4}-\d{4})\s+(G\u00fcz|Bahar|Yaz)(\s+Muafiyet)?/;

    const noiseTokens = new Set(['Sil', 'Tkr', 'E\u015fd', 'Yrn', 'Kld']);

    const courses = [];
    let idCounter = 0;
    let currentSemester = 'Bilinmiyor';
    let detectedFaculty = null;
    let detectedDepartment = null;

    pages.forEach(pageText => {
        const lines = pageText.split('\n').map(l => l.trim()).filter(Boolean);

        for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
            const line = lines[lineIdx];

            // --- Semester detection ---
            const semMatch = line.match(semRe);
            if (semMatch) {
                currentSemester = semMatch[1] + ' ' + semMatch[2] + (semMatch[3] ? ' Muafiyet' : '');
                continue;
            }

            // --- Faculty/department detection ---
            if (!detectedFaculty) {
                const m = line.match(/([A-Z\u00c7\u011e\u0130\u00d6\u015e\u00dc\s]+(?:FAK\u00dcLTES\u0130|ENST\u0130T\u00dc|\u0130S\u00dc|YÜKSEKOKULU|MYO))\s*\(\d+\)/i);
                if (m) detectedFaculty = m[1].trim();
            }
            if (!detectedDepartment) {
                const m = line.match(/([A-Za-z\u00c7\u011e\u0130\u00d6\u015e\u00dc\u00e7\u011f\u0131\u00f6\u015f\u00fc\s]+(?:M\u00dchend|B\u00f6l\u00fcm|Program|Anabilim)\S*)\s*\(\d+\)/i);
                if (m && !/fak\u00fcltesi|enstitüsü|yüksekokulu|myo/i.test(m[1])) {
                    detectedDepartment = m[1].trim();
                }
            }

            // --- Course code detection (first token of line) ---
            const firstToken = line.split(/\s+/)[0];
            if (!codeRe.test(firstToken)) continue;

            const code = firstToken;

            // Collect tokens: rest of current line + look ahead up to 6 more lines.
            // We do NOT stop early when grade is found — AKTS may be on a later line.
            // We DO stop at: next course code, semester header, or section summary rows.
            let collectedTokens = line.split(/\s+/).slice(1).filter(Boolean);

            for (let ahead = 1; ahead <= 6; ahead++) {
                const nextIdx = lineIdx + ahead;
                if (nextIdx >= lines.length) break;
                const nextLine = lines[nextIdx].trim();
                if (!nextLine) continue;
                const nextFirst = nextLine.split(/\s+/)[0];
                // Stop at next course code or semester header
                if (codeRe.test(nextFirst) || semRe.test(nextLine)) break;
                // Stop at semester summary / legend lines
                if (/D\u00f6nem|Toplam|ANO|AGNO|e-imzal|\u0130mzal/i.test(nextLine)) break;
                collectedTokens.push(...nextLine.split(/\s+/).filter(Boolean));
            }

            if (!collectedTokens.some(t => validGrades.has(t))) {
                console.log('[HacettepeParser] No grade for course:', code, '| tokens:', collectedTokens.join(' '));
                continue;
            }

            // Skip courses marked as deleted ("Sil" in Ders Durumu column)
            if (collectedTokens.includes('Sil')) continue;

            // PDF.js extracts columns in visual left-to-right order:
            //   Name | Durum | AKTS | Puan | Grade    (Grade is LAST)
            // For ongoing courses:
            //   Name | Durum | AKTS | Puan("--") | Grade("--")
            // So we find Grade as the RIGHTMOST valid grade token, then work backwards.

            // --- Grade: rightmost valid grade token ---
            let gradeIdx = -1;
            for (let t = collectedTokens.length - 1; t >= 0; t--) {
                if (validGrades.has(collectedTokens[t])) { gradeIdx = t; break; }
            }
            if (gradeIdx === -1) continue;

            const grade = collectedTokens[gradeIdx];

            // --- Tokens before grade ---
            let beforeGrade = collectedTokens.slice(0, gradeIdx)
                .filter(t => !noiseTokens.has(t));

            // For ongoing ("--" grade): Puan is also "--" sitting just before Grade.
            // Remove it so trailing numerics scan works correctly.
            if (grade === '--' && beforeGrade.length > 0 && beforeGrade[beforeGrade.length - 1] === '--') {
                beforeGrade = beforeGrade.slice(0, -1);
            }

            // --- Collect trailing numeric tokens from the right of beforeGrade ---
            // Expected tail: [...Name tokens...] [Durum?] [AKTS] [Puan]
            // (For ongoing after "--" removal: [...Name tokens...] [Durum?] [AKTS])
            const trailingNums = [];
            let nameEndIdx = beforeGrade.length;
            for (let t = beforeGrade.length - 1; t >= 0; t--) {
                if (/^\d+([,.]\d+)?$/.test(beforeGrade[t])) {
                    trailingNums.unshift(beforeGrade[t]);
                    nameEndIdx = t;
                } else {
                    break;
                }
            }

            // AKTS position within trailingNums:
            // Normal grade  → tail = [Durum?, AKTS, Puan] → AKTS = second-to-last
            // "--" grade     → tail = [Durum?, AKTS]        → AKTS = last
            let akts = 0;
            if (grade === '--') {
                if (trailingNums.length >= 1) {
                    akts = Math.round(parseFloat(trailingNums[trailingNums.length - 1].replace(',', '.')));
                }
            } else {
                if (trailingNums.length >= 2) {
                    akts = Math.round(parseFloat(trailingNums[trailingNums.length - 2].replace(',', '.')));
                }
            }

            if (akts <= 0) {
                console.log('[HacettepeParser] No AKTS for course:', code, '| trailingNums:', JSON.stringify(trailingNums), '| grade:', grade);
                continue;
            }

            // --- Name: tokens before the trailing numeric block ---
            const name = beforeGrade.slice(0, nameEndIdx).join(' ').trim();
            if (!name) continue;

            courses.push({
                id: idCounter++,
                semester: currentSemester,
                code,
                name,
                akts,
                uk: 0,
                grade: grade === '--' ? '-' : grade,
                status: 'Z'
            });
        }
    });

    console.log('[HacettepeParser] Parsed', courses.length, 'courses.');

    if (courses.length === 0) return null;

    // Expose detected header info for autoSelectGraduationByTranscript
    extractHacettepeOfficial._lastInfo = {
        faculty: detectedFaculty,
        department: detectedDepartment
    };

    return courses;
}

// Export for Node.js testing if module.exports is available
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { extractCustomFormat, extractHacettepeOfficial };
}
